/**
 *
 * ScrollAreaCorner is the corner element shown when both scrollbars are visible.
 *
 * [Live Demo](https://www.primereact.org/scrollarea/)
 *
 * @module ScrollAreaCorner
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { ScrollAreaRootInstance } from './ScrollAreaRoot.types';
/**
 * Defines passthrough(pt) options type in ScrollAreaCorner component.
 */
export type ScrollAreaCornerPassThroughType<E> = PassThroughType<ScrollAreaCornerInstance, E>;
/**
 * Defines passthrough(pt) options of ScrollAreaCorner component.
 */
export interface ScrollAreaCornerPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: ScrollAreaCornerPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in ScrollAreaCorner component.
 */
export interface ScrollAreaCornerProps extends BaseComponentProps<ScrollAreaCornerInstance, unknown, ScrollAreaCornerPassThrough> {
}
/**
 * Defines valid state in ScrollAreaCorner component.
 */
export interface ScrollAreaCornerState {
}
/**
 * Defines the methods and properties exposed by ScrollAreaCorner component.
 */
export interface ScrollAreaCornerExposes {
    /**
     * Instance of the ScrollArea component.
     */
    scrollarea: ScrollAreaRootInstance | undefined | null;
}
/**
 * Instance of ScrollAreaCorner component.
 */
export type ScrollAreaCornerInstance = ComponentInstance<ScrollAreaCornerProps, ScrollAreaCornerState, ScrollAreaCornerExposes>;
